import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';
import '../theme/app_theme.dart';

/// Centralized asset registry for instant, zero-delay rendering.
/// Inlines the core brand logo in memory so it is ready on Frame 0 with
/// 0ms latency, zero HTTP requests, and zero decoding blanks.
class AppAssets {
  AppAssets._();

  static const String _logoBase64 =
      '';

  static Uint8List? _logoBytes;
  static Uint8List get logoBytes => _logoBytes ??= base64Decode(_logoBase64);

  static MemoryImage? _logoProvider;
  static MemoryImage get logoProvider => _logoProvider ??= MemoryImage(logoBytes);

  /// Pre-warms the image into Flutter\'s ImageCache prior to runApp().
  /// Guarantees that when the first screen builds, the image is already
  /// decoded in GPU memory and renders synchronously.
  static Future<void> init() async {
    try {
      final provider = logoProvider;
      final ImageStream stream = provider.resolve(ImageConfiguration.empty);
      final Completer<void> completer = Completer<void>();
      late ImageStreamListener listener;
      listener = ImageStreamListener(
        (ImageInfo info, bool synchronousCall) {
          if (!completer.isCompleted) completer.complete();
          stream.removeListener(listener);
        },
        onError: (dynamic error, StackTrace? stackTrace) {
          if (!completer.isCompleted) completer.complete();
          stream.removeListener(listener);
        },
      );
      stream.addListener(listener);
      await completer.future.timeout(
        const Duration(milliseconds: 250),
        onTimeout: () {},
      );
    } catch (_) {}

    // Also prime AssetImage for any legacy call sites
    try {
      const assetProvider = AssetImage('assets/images/logo.png');
      final stream = assetProvider.resolve(ImageConfiguration.empty);
      stream.addListener(ImageStreamListener((_, __) {}));
    } catch (_) {}
  }

  /// Zero-latency logo widget. Always displays immediately.
  /// If decoding is in-flight, renders an elegant brand icon fallback
  /// instead of an empty blank white circle.
  static Widget logo({
    double? width,
    double? height,
    BoxFit fit = BoxFit.contain,
    Widget? fallback,
    Color? fallbackColor,
    double? fallbackSize,
  }) {
    final Widget defaultFallback = Center(
      child: Icon(
        Icons.spa_rounded,
        color: fallbackColor ?? AppTheme.forest,
        size: fallbackSize ??
            ((width != null && height != null)
                ? (width < height ? width : height) * 0.6
                : 22.0),
      ),
    );

    return Image(
      image: logoProvider,
      width: width,
      height: height,
      fit: fit,
      gaplessPlayback: true,
      filterQuality: FilterQuality.medium,
      frameBuilder: (context, child, frame, wasSynchronouslyLoaded) {
        if (wasSynchronouslyLoaded || frame != null) {
          return child;
        }
        return fallback ?? defaultFallback;
      },
      errorBuilder: (context, error, stackTrace) =>
          fallback ?? defaultFallback,
    );
  }
}
